class Solution {
public:
 int minimumBuckets(string street){
  int ans=0,n=street.size();
  for(int i=0;i<n;++i) if(street[i]=='H'){
   if(i>0 && street[i-1]=='B') continue;
   if(i+1<n && street[i+1]=='.'){street[i+1]='B';++ans;}
   else if(i>0 && street[i-1]=='.'){street[i-1]='B';++ans;}
   else return -1;
  }
  return ans;
 }
};
